<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Search, Warning } from '@element-plus/icons-vue'
import { api } from '../api'
import { state, refresh, vehicle, labels, money, dateText, today } from '../store'
import FormDialog from '../components/FormDialog.vue'
import StatusTag from '../components/StatusTag.vue'
import VehicleIdentity from '../components/VehicleIdentity.vue'
const route = useRoute()
const query = reactive({ search: '', status: '' }), page = ref(1), open = ref(false), finishing = ref(null), busy = ref(false), detail = ref(null), initial = ref({})
const filtered = computed(() => state.maintenance.filter(task => (!query.status || task.status === query.status) && (!query.search || `${vehicle(task.vehicle_id).plate}${task.project}${task.assignee}`.includes(query.search))))
watch(query, () => page.value = 1)
watch([() => route.query.detail, () => state.maintenance], ([id]) => { detail.value = state.maintenance.find(task => Number(task.id) === Number(id)) || null }, { immediate: true })
const fields = computed(() => finishing.value ? [{ key: 'cost', label: '实际费用（元）', type: 'number', precision: 2, wide: true }, { key: 'next_date', label: '下次保养日期', type: 'date' }, { key: 'next_mileage', label: '下次保养里程（km）', type: 'number', min: Number(vehicle(finishing.value.vehicle_id).mileage) + 1 }] : [{ key: 'vehicle_id', label: '车辆', type: 'select', wide: true, options: state.vehicles.filter(car => car.status === 'AVAILABLE').map(car => ({ label: `${car.plate} · ${car.model}`, value: car.id })) }, { key: 'type', label: '工单类型', type: 'select', options: [{ label: '维修', value: 'REPAIR' }, { label: '保养', value: 'SERVICE' }] }, { key: 'assignee', label: '处理人员' }, { key: 'project', label: '维修保养项目', type: 'textarea', wide: true, maxlength: 200 }, { key: 'cost', label: '预计费用（元）', type: 'number', precision: 2, wide: true }])
const pendingWork = carId => state.maintenance.find(task => task.vehicle_id === carId && task.status === 'PENDING')
function create(carId) { finishing.value = null; initial.value = { vehicle_id: carId || undefined, type: 'SERVICE', assignee: state.user.name, cost: 0 }; open.value = true }
function complete(task) { finishing.value = task; initial.value = { cost: Number(task.cost), next_date: new Date(Date.now() + 86400000 * 180).toISOString().slice(0, 10), next_mileage: Number(vehicle(task.vehicle_id).mileage) + 5000 }; open.value = true }
async function save(data) { busy.value = true; try { await api.post(finishing.value ? `/maintenance/${finishing.value.id}/complete` : '/maintenance', data); open.value = false; await refresh(); ElMessage.success(finishing.value ? '工单完成，车辆已恢复可用' : '工单已创建') } catch {} finally { busy.value = false } }
async function action(task, type) { try { await ElMessageBox.confirm(type === 'start' ? '开始后车辆将进入维修中，无法办理交车。确认继续？' : '确认取消该工单？', '工单操作'); busy.value = true; await api.post(`/maintenance/${task.id}/${type}`, {}); await refresh(); ElMessage.success('工单状态已更新') } catch {} finally { busy.value = false } }
</script>
<template>
  <section v-if="state.reminders.length" class="maintenance-reminders"><div class="reminder-section-heading"><el-icon><Warning/></el-icon><div><h3>保养提醒</h3><p>提前 {{ state.settings.reminder_days }} 天或 {{ state.settings.reminder_km }} 公里提醒，任一条件满足即触发</p></div><span class="count-badge">{{ state.reminders.length }}</span></div><div v-if="state.reminders.length" class="reminder-cars"><div v-for="car in state.reminders" :key="car.id"><VehicleIdentity :vehicle="car"/><p :class="{ 'text-danger': car.next_service_date < today() }">{{ car.next_service_date }} / {{ car.next_service_mileage }} km</p><el-button type="primary" :icon="Plus" :disabled="car.status !== 'AVAILABLE' || busy" @click="pendingWork(car.id) ? action(pendingWork(car.id), 'start') : create(car.id)">{{ pendingWork(car.id) ? '开始工单' : '创建工单' }}</el-button></div></div></section>
  <section class="panel listing-panel"><div class="filter-bar"><el-input v-model="query.search" :prefix-icon="Search" placeholder="搜索车牌、项目、处理人" clearable class="search-input"/><el-select v-model="query.status" placeholder="全部工单状态" clearable><el-option v-for="status in ['PENDING', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED']" :key="status" :label="labels[status]" :value="status"/></el-select><div class="filter-spacer"></div><el-button type="primary" :icon="Plus" @click="create()">新增工单</el-button></div><div class="listing-caption"><span>维修保养记录 <small>{{ filtered.length }} 项</small></span><span>维修前检查关联预约 · 完成后恢复车辆状态</span></div><el-table :data="filtered.slice((page - 1) * 10, page * 10)"><el-table-column label="车辆" min-width="245"><template #default="{ row }"><VehicleIdentity :vehicle="vehicle(row.vehicle_id)"/></template></el-table-column><el-table-column label="项目" min-width="210"><template #default="{ row }"><span>{{ row.project }}</span><small class="cell-sub">{{ labels[row.type] }} / {{ row.assignee }}</small></template></el-table-column><el-table-column label="费用" width="110"><template #default="{ row }">¥{{ money(row.cost) }}</template></el-table-column><el-table-column label="开始时间" min-width="150"><template #default="{ row }">{{ dateText(row.started_at) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="detail = row">详情</el-button><template v-if="row.status === 'PENDING'"><el-button link type="primary" :disabled="busy" @click="action(row, 'start')">开始</el-button><el-button link type="danger" :disabled="busy" @click="action(row, 'cancel')">取消</el-button></template><el-button v-if="row.status === 'IN_PROGRESS'" link type="primary" @click="complete(row)">完成</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ filtered.length }} 项工单</span><el-pagination v-model:current-page="page" :page-size="10" :total="filtered.length" layout="prev, pager, next"/></div></section>
  <FormDialog v-model="open" :title="finishing ? '完成工单与保养设置' : '新增维修保养工单'" :fields="fields" :initial="initial" :busy="busy" @submit="save"/>
  <el-dialog :model-value="!!detail" @close="detail = null" title="维修保养详情" width="620px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="车辆"><VehicleIdentity :vehicle="vehicle(detail.vehicle_id)"/></el-descriptions-item><el-descriptions-item label="项目">{{ detail.project }}</el-descriptions-item><el-descriptions-item label="人员">{{ detail.assignee }}</el-descriptions-item><el-descriptions-item label="费用">¥{{ money(detail.cost) }}</el-descriptions-item><el-descriptions-item label="开始 / 完成">{{ dateText(detail.started_at) }} / {{ dateText(detail.completed_at) }}</el-descriptions-item><el-descriptions-item label="下次保养">{{ detail.next_date || '未登记' }} / {{ detail.next_mileage || '—' }} km</el-descriptions-item></el-descriptions></el-dialog>
</template>
